mapper.select:
WITH TEMP AS ( SELECT DISTINCT FP2.FINPROD_ID, FP.FINPROD_MARKET_ID FROM FIN_PRODUCT FP LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.APPEAR_MARKET_ID = FP.FINPROD_MARKET_ID LEFT JOIN FIN_PRODUCT FP2 ON FPA.FINPROD_ID = FP2.FINPROD_ID WHERE FP.FINPROD_ID LIKE CONCAT('%', CONCAT(#{finprodId}, '%')) AND FP.FINPROD_TYPE2 = #{bond} )
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName,
T3.FINPROD_ABBR finprodAbbr,
T1.PS ps, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.TRADE_MARKET_MODE tradeMarketMode, T1.ENTRUST_NUM*100 entrustNum, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, NVL(T5.FINISH_AMT,0)*100 finishAmt, round(NVL(T5.FINISH_AMT,0)*100/(decode(T1.ENTRUST_NUM,0,1,T1.ENTRUST_NUM)*100),4)*100 transactioncom, T1.REMARK remark, T1.INV_AIM invAim, T1.PRICE_MODEL priceModel, T7.SETTLE_SPREED settleSpreed, T7.ASSET_TYPE1 assetType1, T7.OUR_ENT_NUM*100 entrustOwnNum, T7.LENDIN_ENT_NUM*100 entrustIntegrateNum,
T7.ASSET_TYPE_10 assetType10, T7.ASSET_TYPE_11 assetType11
FROM ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T3.FINPROD_ID
LEFT JOIN TEMP tp ON T1.FINPROD_ID = tp.FINPROD_ID
LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS where ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME
AND T1.FINPROD_TYPE2 =#{bond}
AND T2.PORTFOLIO_TYPE in (#{portfolioType}, #{portfolioType1}) AND T1.ps != #{PS_T04}
AND (T2.PORTFOLIO_ID IN
null) OR T2.PORTFOLIO_ID IN (
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
null) OR T2.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) or T3.FINPROD_ABBR like concat('%',concat(#{finprodId},'%')) OR tp.FINPROD_MARKET_ID = #{finprodId} )
AND T1.TRADE_MARKET=#{tradeMarket}
AND T1.TRADE_MARKET_MODE=#{tradeMarketMode}
AND T1.TRADE_PLAT=#{tradePlat}
AND T1.PS=#{ps}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.PRICE_MODEL = #{priceModel}
AND T7.ASSET_TYPE1 in
#{item}
AND T7.ASSET_TYPE_10 in
#{item}
AND T7.ASSET_TYPE_11 in
#{item}
AND nvl(T1.TRADE_MARKET, T3.TRADE_MARKET) in
#{currTradeMarket}
AND T1.TRADE_PLAT in
#{tradePlatForm}
order by T1.ENTRUST_ID DESC

SELECT T1.PORTFOLIO_ID code, T1.PORTFOLIO_ID name, T1.PORTFOLIO_NAME shortName, T1.PORTFOLIO_ID hidCode FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
T1.PORTFOLIO_ID like concat('%',concat(#{param},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{param},'%'))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT FINPROD_MARKET_ID code, FINPROD_MARKET_ID name, FINPROD_ABBR shortName, FINPROD_ID hidCode FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND (FINPROD_MARKET_ID like concat('%',concat(#{param},'%')) or FINPROD_ABBR like concat('%',concat(#{param},'%')))
AND TRADE_MARKET in
#{currTradeMarket}

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text, T1.PROFIT_TYPE object FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
and T1.PORTFOLIO_ID = #{initValue}
and T1.PORTFOLIO_ID like concat('%',concat(#{search},'%'))
AND T1.PORTFOLIO_TYPE in
#{portType}

SELECT T1.FINPROD_MARKET_ID id,
T1.FINPROD_ABBR text,
T1.FINPROD_NAME, T1.FINPROD_ID, T1.CALENDAR_ID, T1.TRADE_MARKET, T1.IS_RIGHT,
T2.TYPE_9, T2.TYPE_10, T2.TYPE_11,
T1.VDATE, T1.MDATE, FPA.IS_ISSUE_ASSET, T1.CCY FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD FPA ON T1.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID
T1.FINPROD_TYPE2 = #{assestType}
and T1.FINPROD_MARKET_ID = #{initValue}
and T1.TRADE_MARKET = #{tradeMarket}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))
AND FPA.IS_ISSUE_ASSET = 'Y' AND FPA.APPEAR_MARKET_ID IS NULL
union ALL
SELECT T1.FINPROD_MARKET_ID id,
T1.FINPROD_ABBR text,
T1.FINPROD_NAME, T1.FINPROD_ID, T1.CALENDAR_ID, T1.TRADE_MARKET, T1.IS_RIGHT,
T2.TYPE_9, T2.TYPE_10, T2.TYPE_11,
T1.VDATE, T1.MDATE, FPA.IS_ISSUE_ASSET, T1.CCY FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD FPA ON T1.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID
T1.FINPROD_TYPE2 = #{assestType}
and T1.FINPROD_MARKET_ID = #{initValue}
and T1.TRADE_MARKET = #{tradeMarket}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))
AND (FPA.IS_ISSUE_ASSET = 'N' OR FPA.IS_ISSUE_ASSET IS NULL)
AND T1.TRADE_MARKET in
#{currTradeMarket}
union SELECT interf.SECID id, interf.SECFULLNAME text, interf.SECFULLNAME,
null finprod_id, null, interf.MARKET, null, null, null, null, null, null, null, null FROM INTERF_PAYHSRCSECINFO interf
where interf.SECID not in (select FINPROD_MARKET_ID from FIN_PRODUCT T1 where T1.FINPROD_TYPE2 = #{assestType}
)
AND interf.MARKET in
#{currTradeMarket}
and interf.SECID = #{initValue}
and interf.MARKET = #{tradeMarket}
and ( (interf.SECID) LIKE CONCAT('%', CONCAT(#{search}, '%')) or interf.SECNAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

sql.where:
 	T1.FINPROD_TYPE2 = #{assestType}

	and T1.FINPROD_MARKET_ID = #{initValue}


	and T1.TRADE_MARKET = #{tradeMarket}


	and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%'))
	or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))

mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.ASSET_TYPE1 assetType1,
T6.ASSET_TYPE_10 assetType10, T6.ASSET_TYPE_11 assetType11,
T1.CCY ccy, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.TRADE_MARKET_MODE tradeMarketMode, T1.INV_AIM invAim, T1.AVAILABLE_NUM availableNum, T1.ENTRUST_NUM*100 entrustNum, T6.MIN_AMT minAmt, T1.PRICE price, T1.PRICE_MODEL priceModel, T6.EXER_YIELD*100 exerYield, T6.MATURE_YIELD*100 matureYield, T6.SETTLE_SPREED settleSpeed, T6.SEC_ACCT_ID secAcctId, T6.OUR_ENT_NUM*100 entrustOwnNum, T6.LENDIN_ENT_NUM*100 entrustIntegrateNum, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.chl_id chlId, T1.BUSINESS_MODEL businessModel
FROM ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 =#{bond} LEFT JOIN ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}
union all SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.ASSET_TYPE1 assetType1,
T6.ASSET_TYPE_10 assetType10, T6.ASSET_TYPE_11 assetType11,
T1.CCY ccy, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.TRADE_MARKET_MODE tradeMarketMode, T1.INV_AIM invAim, T1.AVAILABLE_NUM availableNum, T1.ENTRUST_NUM*100 entrustNum, T6.MIN_AMT minAmt, T1.PRICE price, T1.PRICE_MODEL priceModel, T6.EXER_YIELD*100 exerYield, T6.MATURE_YIELD*100 matureYield, T6.SETTLE_SPREED settleSpeed, T6.SEC_ACCT_ID secAcctId, T6.OUR_ENT_NUM*100 entrustOwnNum, T6.LENDIN_ENT_NUM*100 entrustIntegrateNum, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.chl_id chlId , '' businessModel
FROM WFL_ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID AND T3.FINPROD_TYPE2 =#{bond} LEFT JOIN WFL_ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
T1.PORTFOLIO_ID=#{portfolioId}
AND T1.FINPROD_ID = #{finprodId}
AND T1.ENTRUST_ID = #{entrustId}

select DSC_CLEAN_PRICE_B
FROM fin_product fp
left join ptl_sec_valution psv on fp.FINPROD_ID = psv.FINPROD_ID
where psv.cdate = TO_DATE(#{sysdate},'yyyy-mm-dd')
and psv.PORTFOLIO_ID = #{portfolioId}
and fp.FINPROD_MARKET_ID = #{finprodMarketId}
and psv.INV_AIM = #{invAim}

	AND SEC_ACCT_ID = #{chlId}

select.if:
SELECT distinct A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR (PORTFOLIO_ID || A.ACCT_NO) = #{initValue, jdbcType=VARCHAR} )
AND TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}

SELECT SEC_ACCT_ID hidCode, SEC_ACCT_ID code, SEC_ACCT_NAME name, SEC_ACCT_NAME shortName FROM STL_SEC_ACCT_INFO
( STL_SEC_ACCT_INFO.SEC_ACCT_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR STL_SEC_ACCT_INFO.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{initValue, jdbcType=VARCHAR}

mapper.select:
SELECT DECODE(POS_AMT,0,0,TDY_COST_AMT/POS_AMT) FROM (
	SELECT TDY_COST_AMT,POS_AMT,DECODE(POS_AMT,0,0,TDY_COST_AMT/POS_AMT)
	FROM  BOK_STAT_DET_POSIITON  BSDP
	JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = BSDP.BOOKSET_ID
	WHERE FP.FINPROD_MARKET_ID = #{portfolioId}
	AND BUSI_ID = #{finprodId}
	AND BSDP.BOOK_DATE <= TO_DATE(#{sysdate},'yyyy-mm-dd')
	ORDER BY BSDP.BOOK_DATE DESC
)WHERE ROWNUM =1
